      "type": "string",
      "description": "One short English sentence for the office team"
    },
    "tenant_name": {
      "type": "string"
    },
    "flat_code": {
      "type": "string",
      "description": "Flat code like VR12-3B, empty if not stated"
    },
    "language": {
      "type": "string",
      "description": "Two-letter code of the email's language, like en or it"
    }
  },
  "required": ["category", "urgency", "summary", "tenant_name", "flat_code", "language"]
}

parameters.jsCode:
// Compares the AI's answers with the expected labels
const tests = $('Read test emails').all().map(item => item.json);

const results = $input.all().map((item, i) => {
  const test = tests[i];
  const out = item.json.output;
  return {
    id: test.id,
    subject: test.subject,
    expected: `${test.expected_category} / ${test.expected_urgency}`,
    predicted: `${out.category} / ${out.urgency}`,
    category_ok: out.category === test.expected_category,
    urgency_ok: out.urgency === test.expected_urgency,
  };
});

const total = results.length;
const share = n => `${n}/${total} (${Math.round((n / total) * 100)}%)`;
const categoryOk = results.filter(r => r.category_ok).length;
const urgencyOk = results.filter(r => r.urgency_ok).length;
const emergencies = tests.filter(t => t.expected_urgency === 'emergency').length;
const caught = results.filter(
  (r, i) => tests[i].expected_urgency === 'emergency' && r.urgency_ok
).length;

return [{
  json: {
    category_accuracy: share(categoryOk),
    urgency_accuracy: share(urgencyOk),
    emergencies_caught: `${caught}/${emergencies}`,
    mistakes: results.filter(r => !r.category_ok || !r.urgency_ok),
  },
}];
